import Foundation

public enum PacketType: UInt8 {
    case handshake = 0
    case handshakeAck = 1
    case frameHeader = 2
    case frameChunk = 3
    case cursorUpdate = 4
    case inputEvent = 5
    case control = 6
    case ping = 7
    case audioFrame = 8
    case pairingRequest = 9
    case pairingGrant = 10
    case pairingReject = 11
}

public struct PacketHeader {
    public let magic: UInt16
    public let type: PacketType
    public let sequence: UInt32
    public let timestamp: UInt32
    public let flags: UInt8

    public init(type: PacketType, sequence: UInt32, timestamp: UInt32, flags: UInt8 = 0) {
        self.magic = ERDConstants.magic
        self.type = type
        self.sequence = sequence
        self.timestamp = timestamp
        self.flags = flags
    }

    public func serialize() -> Data {
        var data = Data(capacity: ERDConstants.packetHeaderSize)
        var m = magic.littleEndian; data.append(Data(bytes: &m, count: 2))
        var t = type.rawValue;      data.append(Data(bytes: &t, count: 1))
        var s = sequence.littleEndian; data.append(Data(bytes: &s, count: 4))
        var ts = timestamp.littleEndian; data.append(Data(bytes: &ts, count: 4))
        var f = flags;              data.append(Data(bytes: &f, count: 1))
        return data
    }

    public static func deserialize(from data: Data) -> PacketHeader? {
        guard data.count >= ERDConstants.packetHeaderSize else { return nil }
        return data.withUnsafeBytes { raw in
            let magic = raw.loadUnaligned(fromByteOffset: 0, as: UInt16.self).littleEndian
            guard magic == ERDConstants.magic else { return nil }
            guard let type = PacketType(rawValue: raw[2]) else { return nil }
            let seq = raw.loadUnaligned(fromByteOffset: 3, as: UInt32.self).littleEndian
            let ts = raw.loadUnaligned(fromByteOffset: 7, as: UInt32.self).littleEndian
            return PacketHeader(type: type, sequence: seq, timestamp: ts, flags: raw[11])
        }
    }
}

import Foundation

public struct FrameHeaderPayload {
    public let frameId: UInt32
    public let width: UInt16
    public let height: UInt16
    public let isKeyFrame: Bool
    public let totalChunks: UInt16
    public let totalSize: UInt32

    public static let size = 16

    public init(frameId: UInt32, width: UInt16, height: UInt16, isKeyFrame: Bool, totalChunks: UInt16, totalSize: UInt32) {
        self.frameId = frameId; self.width = width; self.height = height
        self.isKeyFrame = isKeyFrame; self.totalChunks = totalChunks; self.totalSize = totalSize
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameHeaderPayload.size)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var w = width.littleEndian;     d.append(Data(bytes: &w, count: 2))
        var h = height.littleEndian;    d.append(Data(bytes: &h, count: 2))
        var kf: UInt8 = isKeyFrame ? 1 : 0; d.append(Data(bytes: &kf, count: 1))
        var tc = totalChunks.littleEndian; d.append(Data(bytes: &tc, count: 2))
        // 1 byte padding
        var pad: UInt8 = 0; d.append(Data(bytes: &pad, count: 1))
        var ts = totalSize.littleEndian; d.append(Data(bytes: &ts, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> FrameHeaderPayload? {
        guard data.count >= size else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let w = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let h = data.subdata(in: 6..<8).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let kf = data[8] != 0
        let tc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let ts = data.subdata(in: 12..<16).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        guard tc <= ERDConstants.maxChunksPerFrame, ts <= ERDConstants.maxFrameBytes else { return nil }
        return FrameHeaderPayload(frameId: fid, width: w, height: h, isKeyFrame: kf, totalChunks: tc, totalSize: ts)
    }
}

public struct FrameChunkPayload {
    public let frameId: UInt32
    public let chunkIndex: UInt16
    public let chunkData: Data

    public static let headerSize = 6

    public init(frameId: UInt32, chunkIndex: UInt16, chunkData: Data) {
        self.frameId = frameId; self.chunkIndex = chunkIndex; self.chunkData = chunkData
    }

    public func serialize() -> Data {
        var d = Data(capacity: FrameChunkPayload.headerSize + chunkData.count)
        var fid = frameId.littleEndian; d.append(Data(bytes: &fid, count: 4))
        var ci = chunkIndex.littleEndian; d.append(Data(bytes: &ci, count: 2))
        d.append(chunkData)
        return d
    }

    public static func deserialize(from data: Data) -> FrameChunkPayload? {
        guard data.count >= headerSize else { return nil }
        let fid = data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let ci = data.subdata(in: 4..<6).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let chunk = data.subdata(in: headerSize..<data.count)
        return FrameChunkPayload(frameId: fid, chunkIndex: ci, chunkData: chunk)
    }
}

import Foundation

public enum InputEventType: UInt8 {
    case mouseMove = 0
    case leftMouseDown = 1
    case leftMouseUp = 2
    case rightMouseDown = 3
    case rightMouseUp = 4
    case scrollWheel = 5
    case keyDown = 6
    case keyUp = 7
    case flagsChanged = 8
    case leftMouseDragged = 9
    case rightMouseDragged = 10
}

public struct ModifierFlags: OptionSet {
    public let rawValue: UInt16
    public init(rawValue: UInt16) { self.rawValue = rawValue }

    public static let shift   = ModifierFlags(rawValue: 1 << 0)
    public static let control = ModifierFlags(rawValue: 1 << 1)
    public static let option  = ModifierFlags(rawValue: 1 << 2)
    public static let command = ModifierFlags(rawValue: 1 << 3)
    public static let capsLock = ModifierFlags(rawValue: 1 << 4)
}

public struct InputEventPayload {
    public let type: InputEventType
    public let x: Float
    public let y: Float
    public let keyCode: UInt16
    public let modifiers: ModifierFlags
    public let scrollDeltaX: Float
    public let scrollDeltaY: Float

    public static let size = 21

    public init(type: InputEventType, x: Float, y: Float, keyCode: UInt16 = 0,
                modifiers: ModifierFlags = [], scrollDeltaX: Float = 0, scrollDeltaY: Float = 0) {
        self.type = type; self.x = x; self.y = y; self.keyCode = keyCode
        self.modifiers = modifiers; self.scrollDeltaX = scrollDeltaX; self.scrollDeltaY = scrollDeltaY
    }

    public func serialize() -> Data {
        var d = Data(capacity: InputEventPayload.size)
        var t = type.rawValue; d.append(Data(bytes: &t, count: 1))
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var kc = keyCode.littleEndian; d.append(Data(bytes: &kc, count: 2))
        var mf = modifiers.rawValue.littleEndian; d.append(Data(bytes: &mf, count: 2))
        var sdx = scrollDeltaX.bitPattern.littleEndian; d.append(Data(bytes: &sdx, count: 4))
        var sdy = scrollDeltaY.bitPattern.littleEndian; d.append(Data(bytes: &sdy, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> InputEventPayload? {
        guard data.count >= size else { return nil }
        guard let t = InputEventType(rawValue: data[0]) else { return nil }
        let x = Float(bitPattern: data.subdata(in: 1..<5).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 5..<9).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let kc = data.subdata(in: 9..<11).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }
        let mf = ModifierFlags(rawValue: data.subdata(in: 11..<13).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        let sdx = Float(bitPattern: data.subdata(in: 13..<17).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let sdy = Float(bitPattern: data.subdata(in: 17..<21).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return InputEventPayload(type: t, x: x, y: y, keyCode: kc, modifiers: mf, scrollDeltaX: sdx, scrollDeltaY: sdy)
    }
}

import Foundation

public struct HandshakeCapabilities: OptionSet {
    public let rawValue: UInt64

    public init(rawValue: UInt64) {
        self.rawValue = rawValue
    }

    public static let streamConfiguration = HandshakeCapabilities(rawValue: 1 << 0)
    public static let clipboardSync = HandshakeCapabilities(rawValue: 1 << 1)
    public static let textClipboardSync = HandshakeCapabilities(rawValue: 1 << 2)
}

public struct HandshakePayload {
    public let hostname: String
    public let screenWidth: UInt16
    public let screenHeight: UInt16
    public let scaleFactor: Float
    public let protocolVersion: UInt8
    public let capabilities: HandshakeCapabilities
    public let pairingID: String
    public let sessionSalt: Data

    public init(hostname: String, screenWidth: UInt16, screenHeight: UInt16, scaleFactor: Float, protocolVersion: UInt8 = ERDConstants.protocolVersion, capabilities: HandshakeCapabilities = [], pairingID: String = "", sessionSalt: Data = Data()) {
        self.hostname = hostname
        self.screenWidth = screenWidth
        self.screenHeight = screenHeight
        self.scaleFactor = scaleFactor
        self.protocolVersion = protocolVersion
        self.capabilities = capabilities
        self.pairingID = pairingID
        self.sessionSalt = sessionSalt
    }

    public func serialize() -> Data {
        var data = Data()
        let nameData = hostname.data(using: .utf8) ?? Data()
        var nameLen = UInt16(nameData.count).littleEndian; data.append(Data(bytes: &nameLen, count: 2))
        data.append(nameData)
        var w = screenWidth.littleEndian; data.append(Data(bytes: &w, count: 2))
        var h = screenHeight.littleEndian; data.append(Data(bytes: &h, count: 2))
        var s = scaleFactor.bitPattern.littleEndian; data.append(Data(bytes: &s, count: 4))
        var version = protocolVersion; data.append(Data(bytes: &version, count: 1))
        var flags = capabilities.rawValue.littleEndian; data.append(Data(bytes: &flags, count: 8))
        let idData = Data(pairingID.utf8).prefix(256)
        var idLen = UInt16(idData.count).littleEndian; data.append(Data(bytes: &idLen, count: 2))
        data.append(idData)
        data.append(sessionSalt.prefix(16))
        return data
    }

    public static func deserialize(from data: Data) -> HandshakePayload? {
        guard data.count >= 2 else { return nil }
        var offset = 0
        let nameLen = Int(data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        offset += 2
        guard nameLen <= 1024, data.count >= offset + nameLen + 8 else { return nil }
        let hostname = String(data: data.subdata(in: offset..<offset+nameLen), encoding: .utf8) ?? ""
        offset += nameLen
        let w = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let h = data.subdata(in: offset..<offset+2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian }; offset += 2
        let sBits = data.subdata(in: offset..<offset+4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian }
        let s = Float(bitPattern: sBits)
        offset += 4

        var protocolVersion = ERDConstants.legacyProtocolVersion
        var capabilities: HandshakeCapabilities = []
        var pairingID = ""
        var sessionSalt = Data()
        if data.count >= offset + 9 {
            protocolVersion = data[offset]
            let flags = data.subdata(in: (offset + 1)..<(offset + 9)).withUnsafeBytes { $0.load(as: UInt64.self).littleEndian }
            capabilities = HandshakeCapabilities(rawValue: flags)
            offset += 9
            if data.count >= offset + 2 {
                let idLen = Int(data.subdata(in: offset..<(offset + 2)).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
                offset += 2
                guard idLen <= 256, data.count >= offset + idLen else { return nil }
                pairingID = String(data: data.subdata(in: offset..<(offset + idLen)), encoding: .utf8) ?? ""
                offset += idLen
                if data.count >= offset + 16 {
                    sessionSalt = data.subdata(in: offset..<(offset + 16))
                }
            }
        }

        return HandshakePayload(hostname: hostname, screenWidth: w, screenHeight: h, scaleFactor: s, protocolVersion: protocolVersion, capabilities: capabilities, pairingID: pairingID, sessionSalt: sessionSalt)
    }
}

import Foundation

/// Client -> host: request device pairing. Sent over the PIN-protected
/// bootstrap TLS channel before any screen or input capability is granted.
public struct PairingRequestPayload {
    public let hostname: String

    public init(hostname: String) {
        self.hostname = hostname
    }

    public func serialize() -> Data {
        let nameData = Data(hostname.utf8).prefix(Int(UInt16.max))
        var d = Data(capacity: 2 + nameData.count)
        var nameLen = UInt16(nameData.count).littleEndian
        d.append(Data(bytes: &nameLen, count: 2))
        d.append(nameData)
        return d
    }

    public static func deserialize(from data: Data) -> PairingRequestPayload? {
        guard data.count >= 2 else { return nil }
        let nameLen = Int(data.subdata(in: 0..<2).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        guard nameLen <= 1024, data.count >= 2 + nameLen else { return nil }
        let hostname = String(data: data.subdata(in: 2..<(2 + nameLen)), encoding: .utf8) ?? ""
        return PairingRequestPayload(hostname: hostname)
    }
}

/// Host -> client: the pairing grant. `key` is the 256-bit pairing key the
/// client must persist; `hostName` is the display name the client stores for
/// future connections.
public struct PairingGrantPayload {
    public let pairingID: String
    public let hostName: String
    public let key: Data

    public init(pairingID: String, hostName: String, key: Data) {
        self.pairingID = pairingID
        self.hostName = hostName
        self.key = key
    }

    public func serialize() -> Data {
        let idData = Data(pairingID.utf8).prefix(Int(UInt8.max))
        let nameData = Data(hostName.utf8).prefix(Int(UInt16.max))
        var d = Data(capacity: 2 + idData.count + 2 + nameData.count + 1 + key.count)
        var idLen = UInt8(idData.count); d.append(Data(bytes: &idLen, count: 1))
        d.append(idData)
        var nameLen = UInt16(nameData.count).littleEndian
        d.append(Data(bytes: &nameLen, count: 2))
        d.append(nameData)
        var keyLen = UInt8(key.count); d.append(Data(bytes: &keyLen, count: 1))
        d.append(key)
        return d
    }

    public static func deserialize(from data: Data) -> PairingGrantPayload? {
        guard data.count >= 1 else { return nil }
        let idLen = Int(data[0])
        var offset = 1
        guard data.count >= offset + idLen + 2 else { return nil }
        let pairingID = String(data: data.subdata(in: offset..<(offset + idLen)), encoding: .utf8) ?? ""
        offset += idLen
        let nameLen = Int(data.subdata(in: offset..<(offset + 2)).withUnsafeBytes { $0.load(as: UInt16.self).littleEndian })
        offset += 2
        guard data.count >= offset + nameLen + 1 else { return nil }
        let hostName = String(data: data.subdata(in: offset..<(offset + nameLen)), encoding: .utf8) ?? ""
        offset += nameLen
        let keyLen = Int(data[offset])
        offset += 1
        guard keyLen == 32, data.count >= offset + keyLen else { return nil }
        let key = data.subdata(in: offset..<(offset + keyLen))
        return PairingGrantPayload(pairingID: pairingID, hostName: hostName, key: key)
    }
}

public enum PairingRejectReason: UInt8 {
    case deniedByHost = 0
    case lockedOut = 1
    case pairingDisabled = 2
}

public struct PairingRejectPayload {
    public let reason: PairingRejectReason

    public init(reason: PairingRejectReason) {
        self.reason = reason
    }

    public func serialize() -> Data {
        var r = reason.rawValue
        return Data(bytes: &r, count: 1)
    }

    public static func deserialize(from data: Data) -> PairingRejectPayload? {
        guard data.count >= 1, let reason = PairingRejectReason(rawValue: data[0]) else { return nil }
        return PairingRejectPayload(reason: reason)
    }
}

import Foundation

public enum ControlMessageType: UInt8 {
    case requestKeyFrame = 0
    case startStream = 1
    case stopStream = 2
    case disconnect = 3
    case ping = 4
    case pong = 5
    case bitrateAdjust = 6
    case streamConfigRequest = 7
    case streamConfigResponse = 8
    case streamConfigReject = 9
    case streamConfigError = 10
    case clipboardSyncRequest = 11
    case clipboardSyncUpdate = 12
    case clipboardSyncError = 13
}

public struct ControlMessage {
    public let type: ControlMessageType
    public let payload: Data?

    public init(type: ControlMessageType, payload: Data? = nil) {
        self.type = type
        self.payload = payload
    }

    public func serialize() -> Data {
        var d = Data([type.rawValue])
        if let payload = payload {
            d.append(payload)
        }
        return d
    }

    public static func deserialize(from data: Data) -> ControlMessage? {
        guard data.count >= 1, let t = ControlMessageType(rawValue: data[0]) else { return nil }
        let payload: Data? = data.count > 1 ? data.subdata(in: 1..<data.count) : nil
        return ControlMessage(type: t, payload: payload)
    }
}

public struct BitrateAdjustPayload {
    public let targetBitrate: Int32

    public static let size = 4

    public init(targetBitrate: Int32) {
        self.targetBitrate = targetBitrate
    }

    public func serialize() -> Data {
        var d = Data(capacity: BitrateAdjustPayload.size)
        var br = targetBitrate.littleEndian
        d.append(Data(bytes: &br, count: 4))
        return d
    }

    public static func deserialize(from data: Data) -> BitrateAdjustPayload? {
        guard data.count >= size else { return nil }
        let br = data.withUnsafeBytes { $0.load(as: Int32.self).littleEndian }
        return BitrateAdjustPayload(targetBitrate: br)
    }
}

public struct CursorUpdate {
    public let x: Float
    public let y: Float
    public let cursorType: UInt8

    public static let size = 9

    public init(x: Float, y: Float, cursorType: UInt8 = 0) {
        self.x = x; self.y = y; self.cursorType = cursorType
    }

    public func serialize() -> Data {
        var d = Data(capacity: CursorUpdate.size)
        var fx = x.bitPattern.littleEndian; d.append(Data(bytes: &fx, count: 4))
        var fy = y.bitPattern.littleEndian; d.append(Data(bytes: &fy, count: 4))
        var ct = cursorType; d.append(Data(bytes: &ct, count: 1))
        return d
    }

    public static func deserialize(from data: Data) -> CursorUpdate? {
        guard data.count >= size else { return nil }
        let x = Float(bitPattern: data.subdata(in: 0..<4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        let y = Float(bitPattern: data.subdata(in: 4..<8).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
        return CursorUpdate(x: x, y: y, cursorType: data[8])
    }
}

public class AtomicBool {
    private let lock = NSLock()
    private var _value: Bool

    public init(_ value: Bool = false) { _value = value }

    public var value: Bool {
        get { lock.lock(); defer { lock.unlock() }; return _value }
        set { lock.lock(); defer { lock.unlock() }; _value = newValue }
    }
}

import Foundation
import CryptoKit
import Security
import CommonCrypto

// Cryptographic core of the v3 wire protocol.
//
// TCP runs TLS 1.3 with external PSKs: a bootstrap PSK derived from an
// 8-digit PIN plus a per-connection salt, or a 256-bit random pairing key
// persisted in the Keychain after first approval (see ERDIdentity).
// UDP datagrams are sealed with AES-256-GCM under direction-separated keys
// derived from the pairing key and a per-session salt.
//
// HKDF is implemented locally because CryptoKit's HKDF API requires macOS 14
// while EclipticRD targets macOS 13.

/// RFC 5869 HKDF-SHA256 (Extract/Expand); test vectors live in the XCTest target.
enum HKDF {
    static func extract(salt: Data, ikm: Data) -> Data {
        let key = SymmetricKey(data: salt.isEmpty ? Data(repeating: 0, count: 32) : salt)
        return Data(HMAC<SHA256>.authenticationCode(for: ikm, using: key))
    }

    static func expand(prk: Data, info: Data, length: Int) -> Data {
        precondition(length >= 0 && length <= 255 * 32, "HKDF-Expand length out of range")
        var okm = Data()
        var t = Data()
        var counter: UInt8 = 1
        while okm.count < length {
            var input = t
            input.append(info)
            input.append(counter)
            t = Data(HMAC<SHA256>.authenticationCode(for: input, using: SymmetricKey(data: prk)))
            okm.append(t)
            counter &+= 1
        }
        return okm.prefix(length)
    }

    static func derive(ikm: Data, salt: Data, info: Data, length: Int = 32) -> Data {
        expand(prk: extract(salt: salt, ikm: ikm), info: info, length: length)
    }
}

/// AES-256-GCM cipher for UDP datagrams with sliding-window replay protection.
///
/// Datagram wire format: `[12-byte nonce][ciphertext][16-byte tag]`
/// Nonce layout: `[4-byte session prefix][8-byte big-endian packet counter]`.
/// Prefix and traffic key are direction-separated, so nonce reuse across the
/// two directions is impossible even under counter resets.
public final class DatagramCipher: @unchecked Sendable {
    public static let nonceSize = 12
    public static let tagSize = 16
    public static let windowSize: UInt64 = 4096

    private let key: SymmetricKey
    private let noncePrefix: [UInt8] // 4 bytes, derived per direction per session
    private let lock = NSLock()
    private var sendCounter: UInt64 = 0
    private var highestReceived: UInt64 = 0
    private var receivedBlocks: [UInt64: UInt64] = [:] // block index -> 64-bit seen mask

    init(key: Data, noncePrefix: Data) {
        precondition(key.count == 32, "DatagramCipher expects a 256-bit key")
        precondition(noncePrefix.count == 4, "DatagramCipher expects a 4-byte nonce prefix")
        self.key = SymmetricKey(data: key)
        self.noncePrefix = [UInt8](noncePrefix)
    }

    /// Derive the per-direction UDP traffic cipher from the pairing master key
    /// and the session salt exchanged inside the authenticated handshake.
    public static func udpCipher(masterKey: Data, sessionSalt: Data, clientToHost: Bool) -> DatagramCipher {
        let ikm = HKDF.derive(ikm: masterKey, salt: sessionSalt, info: Data("erd/udp-ikm/v3".utf8))
        let info = Data(clientToHost ? "erd/udp-c2h/v3".utf8 : "erd/udp-h2c/v3".utf8)
        let key = HKDF.derive(ikm: ikm, salt: sessionSalt, info: info, length: 32)
        let prefix = HKDF.derive(ikm: ikm, salt: sessionSalt, info: info + Data("/nonce".utf8), length: 4)
        return DatagramCipher(key: key, noncePrefix: prefix)
    }

    /// Encrypt `plaintext`; returns nonce||ciphertext||tag, or nil on internal failure.
    public func seal(_ plaintext: Data, aad: Data = Data()) -> Data? {
        lock.lock()
        sendCounter &+= 1
        let counter = sendCounter
        lock.unlock()

        var nonceBytes = noncePrefix
        var bigCounter = counter.bigEndian
        withUnsafeBytes(of: &bigCounter) { nonceBytes.append(contentsOf: $0) }
        guard let nonce = try? AES.GCM.Nonce(data: Data(nonceBytes)),
              let box = try? AES.GCM.seal(plaintext, using: key, nonce: nonce, authenticating: aad)
        else { return nil }
        return Data(nonceBytes) + box.ciphertext + box.tag
    }

    /// Decrypt a datagram produced by `seal`. Returns nil for tampered,
    /// duplicated, or too-old packets. Thread-safe.
    public func open(_ datagram: Data, aad: Data = Data()) -> Data? {
        guard datagram.count > Self.nonceSize + Self.tagSize else { return nil }
        let nonceData = datagram.subdata(in: 0..<Self.nonceSize)
        let counter = nonceData.subdata(in: 4..<12).withUnsafeBytes { $0.load(as: UInt64.self).bigEndian }
        let ciphertext = datagram.subdata(in: Self.nonceSize..<(datagram.count - Self.tagSize))
        let tag = datagram.subdata(in: (datagram.count - Self.tagSize)..<datagram.count)

        lock.lock(); defer { lock.unlock() }

        // Replay window fast reject (overflow-safe: never add to a wire value).
        guard highestReceived <= counter || highestReceived - counter < Self.windowSize else { return nil }
        let block = counter / 64
        let mask: UInt64 = 1 << (counter % 64)
        if (receivedBlocks[block] ?? 0) & mask != 0 { return nil }

        guard let nonce = try? AES.GCM.Nonce(data: nonceData),
              let box = try? AES.GCM.SealedBox(nonce: nonce, ciphertext: ciphertext, tag: tag),
              let plaintext = try? AES.GCM.open(box, using: key, authenticating: aad)
        else { return nil }

        receivedBlocks[block, default: 0] |= mask
        if counter > highestReceived { highestReceived = counter }
        let cutoff = highestReceived >= Self.windowSize ? (highestReceived - Self.windowSize) / 64 : 0
        if receivedBlocks.count > 128 {
            receivedBlocks = receivedBlocks.filter { $0.key >= cutoff }
        }
        return plaintext
    }
}

/// Shared helpers for the identity material backing the TLS-PSK channels.
public enum ERDCrypto {
    /// TLS-PSK for a bootstrap (first-time pairing) connection. The host
    /// rotates the PIN per pairing session, so each session gets a fresh key
    /// without per-connection salt negotiation.
    ///
    /// The PIN is PBKDF2-stretched so an attacker who records the bootstrap
    /// handshake cannot brute-force it offline with cheap HMAC evaluations.
    public static func bootstrapPSK(pin: String) -> Data {
        let stretched = stretch(Data(pin.utf8),
                                salt: Data("erd/bootstrap/v3".utf8),
                                rounds: ERDConstants.bootstrapPINStretchRounds)
        return HKDF.derive(ikm: stretched,
                           salt: Data("erd/bootstrap/v3".utf8),
                           info: Data("erd/tls-psk".utf8))
    }

    /// PBKDF2-SHA256 (CommonCrypto), 32-byte output. Roughly 0.3s per call at
    /// the configured round count — the derivation runs once per pairing
    /// window, never per packet.
    private static func stretch(_ secret: Data, salt: Data, rounds: UInt32) -> Data {
        var derived = Data(repeating: 0, count: 32)
        let status = derived.withUnsafeMutableBytes { derivedBytes in
            secret.withUnsafeBytes { secretBytes in
                salt.withUnsafeBytes { saltBytes in
                    CCKeyDerivationPBKDF(
                        CCPBKDFAlgorithm(kCCPBKDF2),
                        secretBytes.baseAddress?.assumingMemoryBound(to: Int8.self), secret.count,
                        saltBytes.baseAddress?.assumingMemoryBound(to: UInt8.self), salt.count,
                        CCPseudoRandomAlgorithm(kCCPRFHmacAlgSHA256), rounds,
                        derivedBytes.baseAddress?.assumingMemoryBound(to: UInt8.self), 32)
                }
            }
        }
        precondition(status == kCCSuccess, "PBKDF2 failed: \(status)")
        return derived
    }

    /// PSK for a paired device: the raw 256-bit Keychain pairing key.
    public static func pairingPSK(_ key: Data) -> Data { key }

    /// Uniform 32-byte random key material.
    public static func randomKey() -> Data {
        var key = Data(count: 32)
        let status = key.withUnsafeMutableBytes {
            SecRandomCopyBytes(kSecRandomDefault, 32, $0.baseAddress!)
        }
        precondition(status == errSecSuccess, "SecRandomCopyBytes failed: \(status)")
        return key
    }

    /// 8-digit zero-padded bootstrap PIN from the system RNG.
    public static func randomPIN(digits: Int = ERDConstants.pinLength) -> String {
        var value: UInt64 = 0
        let bound = UInt64(1) << (6 * digits) // keep modulo bias negligible
        repeat {
            let status = withUnsafeMutableBytes(of: &value) {
                SecRandomCopyBytes(kSecRandomDefault, 8, $0.baseAddress!)
            }
            precondition(status == errSecSuccess, "SecRandomCopyBytes failed: \(status)")
        } while value >= UInt64.max - (UInt64.max % bound)
        let modulus = UInt64(pow(10.0, Double(digits)))
        let number = String(value % modulus)
        return String(repeating: "0", count: max(0, digits - number.count)) + number
    }
}

import Foundation
import Network
import Security

/// Transport security selection for a TCP channel.
///
/// `.psk` upgrades the channel to TLS 1.3 with external pre-shared keys.
/// The host offers one PSK per paired device plus the pending bootstrap key
/// (see PairingManager.hostPSKs); the client offers exactly one. Identity
/// strings on the wire pick the key, so no certificates are involved.
public enum ChannelSecurity {
    case none
    case psk([ERDPSK])

    var tlsParameters: NWParameters? {
        guard case let .psk(psks) = self, !psks.isEmpty else { return nil }
        return Self.tlsOptions(psks)
    }

    static func tlsOptions(_ psks: [ERDPSK]) -> NWParameters {
        let options = NWProtocolTLS.Options()
        let sec = options.securityProtocolOptions
        for psk in psks {
            sec_protocol_options_add_pre_shared_key(sec,
                                                    Self.dispatchData(psk.key) as dispatch_data_t,
                                                    Self.dispatchData(Data(psk.identity.utf8)) as dispatch_data_t)
        }
        sec_protocol_options_set_min_tls_protocol_version(sec, .TLSv12)
        sec_protocol_options_set_max_tls_protocol_version(sec, .TLSv13)
        // PSK-only TLS exchanges no certificate; the transcript MAC binds
        // both sides to the shared key, which is the authentication. Reading
        // back the negotiated PSK identity (to cross-check the app-layer
        // pairing id) is not possible: Security exposes
        // sec_protocol_metadata_access_pre_shared_keys with a C-only
        // dispatch_data_t that Swift cannot introspect.
        sec_protocol_options_set_verify_block(sec, { _, _, complete in complete(true) }, DispatchQueue.global(qos: .userInitiated))
        return NWParameters(tls: options)
    }

    private static func dispatchData(_ data: Data) -> DispatchData {
        // DispatchData(bytes:) copies the buffer (default destructor), so the
        // result outlives the Data storage.
        data.withUnsafeBytes { DispatchData(bytes: $0) }
    }
}

public class TCPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.tcp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var receiveBuffer = Data()
    private var timeoutWorkItem: DispatchWorkItem?
    private var didNotifyDisconnect = false
    public var security: ChannelSecurity
    private var listenPort: UInt16?

    public var onConnect: (@Sendable () -> Void)?
    public var onDisconnect: (@Sendable () -> Void)?
    public var onReceive: (@Sendable (Data) -> Void)?
    public var onConnectionFailed: (@Sendable () -> Void)?
    public private(set) var lastFailureDescription: String?
    public private(set) var connectionStateDescription: String?

    public var remoteHostIP: String? {
        guard let endpoint = connection?.currentPath?.remoteEndpoint else { return nil }
        if case .hostPort(let host, _) = endpoint { return "\(host)" }
        return nil
    }

    public init(security: ChannelSecurity = .none) {
        self.security = security
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    private var connectionParameters: NWParameters {
        let params = security.tlsParameters ?? NWParameters.tcp
        // Pairing swaps PSKs by restarting the listener; without endpoint
        // reuse the immediate rebind loses the race with the old socket.
        params.allowLocalEndpointReuse = true
        return params
    }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        listenPort = port
        listener = try NWListener(using: connectionParameters, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            self?.setupConnection(conn)
        }
        listener?.stateUpdateHandler = { state in
            ERDLog.network("[TCP] Listener state: \(state)")
        }
        listener?.start(queue: queue)
    }

    public func advertiseService(name: String) {
        listener?.service = NWListener.Service(name: name, type: ERDConstants.bonjourServiceType, domain: ERDConstants.bonjourDomain)
    }

    /// Swap the offered PSKs (e.g. after a pairing grant) and restart the
    /// listener once the old one has fully released its port.
    public func updateSecurity(_ newSecurity: ChannelSecurity) {
        queue.async { [weak self] in
            guard let self = self else { return }
            self.security = newSecurity
            guard let port = self.listenPort, let old = self.listener else { return }
            self.listener = nil
            old.stateUpdateHandler = { [weak self] state in
                if case .cancelled = state {
                    old.stateUpdateHandler = nil
                    self?.rebindListener(port: port, attempts: 3)
                }
            }
            old.cancel()
        }
    }

    /// Rebind with bounded retries — on slower machines the cancelled
    /// listener's port can linger briefly past the .cancelled callback.
    private func rebindListener(port: UInt16, attempts: Int) {
        do {
            try startListening(port: port)
        } catch {
            guard attempts > 1 else {
                ERDLog.error("[TCP] Listener rebind failed permanently: \(error)")
                return
            }
            ERDLog.warning("[TCP] Listener rebind failed (\(attempts - 1) retries left), retrying...")
            queue.asyncAfter(deadline: .now() + 0.3) { [weak self] in
                self?.rebindListener(port: port, attempts: attempts - 1)
            }
        }
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let conn = NWConnection(to: endpoint, using: connectionParameters)
        queue.async { [weak self] in
            self?.setupConnection(conn)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func connectICE(endpoints: [NWEndpoint]) {
        for endpoint in endpoints {
            let conn = NWConnection(to: endpoint, using: connectionParameters)
            conn.stateUpdateHandler = { [weak self] state in
                guard let self = self else { return }
                switch state {
                case .ready:
                    if self.connection == nil {
                        self.connection = conn
                        self.didNotifyDisconnect = false
                        self.cancelTimeout()
                        ERDLog.network("[Client] ICE Won by \(endpoint)")
                        conn.stateUpdateHandler = { [weak self] state in
                            switch state {
                            case .ready:
                                break
                            case .failed(let err):
                                ERDLog.error("[TCP] ICE connection failed: \(err)")
                                self?.notifyDisconnect()
                            case .cancelled:
                                self?.notifyDisconnect()
                            default:
                                break
                            }
                        }
                        self.startReceiving()
                        self.onConnect?()
                    } else {
                        conn.cancel()
                    }
                case .failed, .cancelled:
                    break
                default: break
                }
            }
            conn.start(queue: queue)
        }
        setTimeout(ERDConstants.connectionTimeout)
    }

    public func setTimeout(_ seconds: Double) {
        queue.async { [weak self] in
            self?.cancelTimeout()
            let work = DispatchWorkItem { [weak self] in
                guard let self = self else { return }
                ERDLog.error("[TCP] Connection timeout after \(seconds)s")
                self.connection?.cancel()
                self.connection = nil
                self.notifyDisconnect()
            }
            self?.timeoutWorkItem = work
            self?.queue.asyncAfter(deadline: .now() + seconds, execute: work)
        }
    }

    // MARK: - Send

    public func send(_ data: Data) {
        // Length-prefixed framing: 4-byte little-endian length + payload
        var len = UInt32(data.count).littleEndian
        var frame = Data(bytes: &len, count: 4)
        frame.append(data)
        connection?.send(content: frame, completion: .contentProcessed { error in
            if let error = error {
                ERDLog.error("[TCP] Send error: \(error)")
            }
        })
    }

    public func sendControl(_ msg: ControlMessage) {
        let header = PacketHeader(type: .control, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(msg.serialize())
        send(packet)
    }

    public func sendInput(_ input: InputEventPayload) {
        let header = PacketHeader(type: .inputEvent, sequence: 0, timestamp: currentTimestamp())
        var packet = header.serialize()
        packet.append(input.serialize())
        send(packet)
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    public func disconnectConnection() {
        let work = {
            self.cancelTimeout()
            self.connection?.cancel()
            self.connection = nil
            self.receiveBuffer = Data()
            self.notifyDisconnect()
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func cancelTimeout() {
        timeoutWorkItem?.cancel()
        timeoutWorkItem = nil
    }

    private func setupConnection(_ conn: NWConnection) {
        connection = conn
        didNotifyDisconnect = false
        var becameReady = false
        conn.stateUpdateHandler = { [weak self] state in
            self?.connectionStateDescription = "\(state)"
            switch state {
            case .ready:
                becameReady = true
                self?.cancelTimeout()
                ERDLog.network("[TCP] Connected to \(conn.endpoint)")
                self?.startReceiving()
                self?.onConnect?()
            case .failed(let err):
                ERDLog.error("[TCP] Connection failed: \(err)")
                if let self {
                    queue.async { self.lastFailureDescription = "\(err)" }
                    // A connection that never became ready failed the TLS
                    // handshake — feed the bootstrap lockout counter.
                    if !becameReady { self.onConnectionFailed?() }
                }
                self?.notifyDisconnect()
            case .cancelled:
                self?.notifyDisconnect()
            default: break
            }
        }
        conn.start(queue: queue)
    }

    private func notifyDisconnect() {
        guard !didNotifyDisconnect else { return }
        didNotifyDisconnect = true
        onDisconnect?()
    }

    private func startReceiving() {
        connection?.receive(minimumIncompleteLength: 1, maximumLength: 262144) { [weak self] content, _, isComplete, error in
            guard let self = self else { return }
            if let data = content {
                self.receiveBuffer.append(data)
                self.processBuffer()
            }
            if let error = error {
                ERDLog.error("[TCP] Receive error: \(error)")
                self.notifyDisconnect()
                return
            }
            if !isComplete {
                self.startReceiving()
            } else {
                self.notifyDisconnect()
            }
        }
    }

    private func processBuffer() {
        while receiveBuffer.count >= 4 {
            let length = Int(receiveBuffer.prefix(4).withUnsafeBytes { $0.load(as: UInt32.self).littleEndian })
            guard length > 0, length <= 16_777_216 else {
                // Invalid length — drop buffer to recover
                ERDLog.error("[TCP] Invalid frame length: \(length), dropping buffer")
                receiveBuffer.removeAll()
                break
            }
            guard receiveBuffer.count >= 4 + length else {
                break
            }
            let payload = receiveBuffer.subdata(in: 4..<(4 + length))
            receiveBuffer.removeSubrange(0..<(4 + length))
            onReceive?(payload)
        }
    }

    private func currentTimestamp() -> UInt32 {
        UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
    }
}

import Foundation
import Network

public class UDPChannel {
    private var connection: NWConnection?
    private var listener: NWListener?
    private let queue = DispatchQueue(label: "eclipticrd.udp", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var sequenceCounter: UInt32 = 0
    private let seqLock = NSLock()
    private let cipherLock = NSLock()
    private var _sendCipher: DatagramCipher?
    private var _receiveCipher: DatagramCipher?
    private var isReceiving = false

    public var onReceive: (@Sendable (Data, NWEndpoint?) -> Void)?
    public var onReady: (@Sendable () -> Void)?

    private let _isReady = AtomicBool(false)
    public var isReady: Bool { _isReady.value }

    /// Direction-separated traffic ciphers: datagrams we emit are sealed with
    /// `sendCipher`, incoming ones opened with `receiveCipher`. Distinct keys
    /// keep the AES-GCM nonce spaces independent per direction.
    public var sendCipher: DatagramCipher? {
        get { cipherLock.lock(); defer { cipherLock.unlock() }; return _sendCipher }
        set { cipherLock.lock(); _sendCipher = newValue; cipherLock.unlock() }
    }

    public var receiveCipher: DatagramCipher? {
        get { cipherLock.lock(); defer { cipherLock.unlock() }; return _receiveCipher }
        set { cipherLock.lock(); _receiveCipher = newValue; cipherLock.unlock() }
    }

    public init() {
        queue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    // MARK: - Server side

    public func startListening(port: UInt16) throws {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        listener = try NWListener(using: params, on: NWEndpoint.Port(rawValue: port)!)
        listener?.newConnectionHandler = { [weak self] conn in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                if case .ready = state {
                    ERDLog.network("[UDP] Listener connection ready")
                    self?._isReady.value = true
                    self?.onReady?()
                }
                self?.reconcileReceiving(conn, state: state)
            }
            conn.start(queue: self.queue)
            self.armReceiving(on: conn)
        }
        listener?.start(queue: queue)
    }

    // MARK: - Client side

    public func connect(host: String, port: UInt16) {
        let endpoint = NWEndpoint.hostPort(host: NWEndpoint.Host(host), port: NWEndpoint.Port(rawValue: port)!)
        connect(to: endpoint)
    }

    public func connect(to endpoint: NWEndpoint) {
        let params = NWParameters.udp
        params.allowLocalEndpointReuse = true
        let conn = NWConnection(to: endpoint, using: params)
        queue.async { [weak self] in
            guard let self = self else { return }
            self.connection = conn
            conn.stateUpdateHandler = { [weak self] state in
                switch state {
                case .ready:
                    ERDLog.network("[UDP] Connected to \(endpoint)")
                    self?._isReady.value = true
                    self?.onReady?()
                case .failed(let e): ERDLog.error("[UDP] Connection failed: \(e)")
                default: break
                }
                self?.reconcileReceiving(conn, state: state)
            }
            conn.start(queue: self.queue)
            self.armReceiving(on: conn)
        }
    }

    // MARK: - Send

    public func send(_ data: Data, to endpoint: NWEndpoint? = nil) {
        guard let conn = connection else { return }
        conn.send(content: data, completion: .contentProcessed { error in
            if let error = error { ERDLog.error("[UDP] Send error: \(error)") }
        })
    }

    public func sendPacket(type: PacketType, payload: Data, to endpoint: NWEndpoint? = nil) {
        seqLock.lock()
        sequenceCounter += 1
        let seq = sequenceCounter
        seqLock.unlock()
        let ts = UInt32(truncatingIfNeeded: UInt64(Date().timeIntervalSince1970 * 1000))
        let header = PacketHeader(type: type, sequence: seq, timestamp: ts)
        var packet = header.serialize()
        if let cipher = sendCipher {
            guard let sealed = cipher.seal(payload, aad: packet) else {
                ERDLog.error("[UDP] Failed to seal \(type) packet")
                return
            }
            packet.append(sealed)
        } else {
            packet.append(payload)
        }
        send(packet, to: endpoint)
    }

    /// Send a small datagram to trigger the other side's listener to register us
    public func sendPing() {
        send(Data([0xFF]))
    }

    // MARK: - Stop

    public func stop() {
        let work = {
            self.connection?.cancel()
            self.connection = nil
            self.listener?.cancel()
            self.listener = nil
            self.sequenceCounter = 0
            self.isReceiving = false
            self._isReady.value = false
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.sync { work() }
        }
    }

    // MARK: - Internal

    private func reconcileReceiving(_ conn: NWConnection, state: NWConnection.State) {
        guard case .ready = state else { return }
        armReceiving(on: conn)
    }

    private func armReceiving(on conn: NWConnection) {
        let work = {
            guard self.connection === conn, !self.isReceiving else { return }
            self.isReceiving = true
            self.receiveLoop(on: conn)
        }
        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            queue.async(execute: work)
        }
    }

    private func receiveLoop(on conn: NWConnection) {
        conn.receiveMessage { [weak self] content, _, _, error in
            guard let self = self else { return }
            if let data = content, data.count > 1 {
                if let packet = self.decodeDatagram(data) {
                    self.onReceive?(packet, conn.currentPath?.remoteEndpoint)
                }
            }
            if let error = error {
                ERDLog.error("[UDP] Receive error: \(error)")
            }
            // receiveMessage reports isComplete == true after datagrams on
            // listener-created UDP connections; only a dead connection may
            // stop the loop.
            let finish = {
                self.isReceiving = false
                switch conn.state {
                case .failed, .cancelled:
                    return
                default:
                    self.armReceiving(on: conn)
                }
            }
            if DispatchQueue.getSpecific(key: Self.queueKey) == true {
                finish()
            } else {
                self.queue.async(execute: finish)
            }
        }
    }

    private func decodeDatagram(_ data: Data) -> Data? {
        guard let cipher = receiveCipher else { return data }
        guard data.count > ERDConstants.packetHeaderSize,
              PacketHeader.deserialize(from: data.prefix(ERDConstants.packetHeaderSize)) != nil
        else { return nil }
        let header = data.prefix(ERDConstants.packetHeaderSize)
        guard let plaintext = cipher.open(data.subdata(in: ERDConstants.packetHeaderSize..<data.count),
                                          aad: Data(header))
        else { return nil }
        return header + plaintext
    }
}

import Foundation
import CryptoKit

public struct SessionCandidate: Codable, Equatable {
    public let role: String
    public let localIP: String
    public let localPort: UInt16
    public let publicIP: String
    public let publicPort: UInt16

    public init(role: String, localIP: String, localPort: UInt16, publicIP: String, publicPort: UInt16) {
        self.role = role; self.localIP = localIP; self.localPort = localPort
        self.publicIP = publicIP; self.publicPort = publicPort
    }
}

/// NAT-traversal candidate exchange over a public ntfy.sh topic.
///
/// The topic is a 256-bit hash of the shared PIN and candidate payloads are
/// AES-GCM encrypted under a key derived from the same PIN, so an outside
/// observer can neither enumerate topics for a given PIN space nor read the
/// exchanged addresses. Both peers poll until the other side's candidate
/// shows up instead of failing on the first empty response.
public class SignalingClient {
    private let role: String
    private let topic: String
    private let payloadKey: SymmetricKey
    private let lock = NSLock()
    private var isSearching = false

    public init(pin: String, role: String) {
        self.role = role
        let ikm = Data(pin.utf8)
        let seed = HKDF.derive(ikm: ikm, salt: Data("erd/signaling/v3".utf8), info: Data("erd/topic".utf8))
        // ntfy.sh rejects topics longer than 64 chars with a 404; 112 bits of
        // derived entropy keeps the topic unenumerable while fitting the cap.
        self.topic = "erd3-" + seed.prefix(14).map { String(format: "%02x", $0) }.joined()
        let key = HKDF.derive(ikm: ikm, salt: Data("erd/signaling/v3".utf8), info: Data("erd/payload-key".utf8))
        self.payloadKey = SymmetricKey(data: key)
    }

    deinit { stop() }

    private static func encrypt(_ payload: Data, using key: SymmetricKey) throws -> String {
        let box = try AES.GCM.seal(payload, using: key)
        return Data(box.combined!).base64EncodedString()
    }

    private static func peerCandidate(in data: Data, excludingRole role: String, key: SymmetricKey) -> SessionCandidate? {
        let lines = String(data: data, encoding: .utf8)?.split(separator: "\n") ?? []
        for line in lines.reversed() {
            guard let lineData = line.data(using: .utf8),
                  let envelope = try? JSONSerialization.jsonObject(with: lineData) as? [String: Any],
                  let message = envelope["message"] as? String,
                  let raw = Data(base64Encoded: message),
                  let box = try? AES.GCM.SealedBox(combined: raw),
                  let payload = try? AES.GCM.open(box, using: key),
                  let candidate = try? JSONDecoder().decode(SessionCandidate.self, from: payload),
                  candidate.role != role
            else { continue }
            return candidate
        }
        return nil
    }

    public func exchangeCandidate(_ local: SessionCandidate) async throws -> SessionCandidate {
        let payload = try JSONEncoder().encode(local)
        let message = try Self.encrypt(payload, using: payloadKey)
        let url = URL(string: "https://ntfy.sh/\(topic)")!

        var post = URLRequest(url: url)
        post.httpMethod = "POST"
        post.httpBody = Data(message.utf8)
        post.setValue("text/plain", forHTTPHeaderField: "Content-Type")

        ERDLog.network("[Signaling] Posting candidate")
        let (_, postResponse) = try await URLSession.shared.data(for: post)
        if let http = postResponse as? HTTPURLResponse, !(200...299).contains(http.statusCode) {
            throw NSError(domain: "Signaling", code: 3,
                          userInfo: [NSLocalizedDescriptionKey: "Candidate POST rejected (HTTP \(http.statusCode))"])
        }

        lock.lock()
        isSearching = true
        lock.unlock()

        let deadline = Date().addingTimeInterval(ERDConstants.connectionTimeout)
        var poll = URLRequest(url: URL(string: "https://ntfy.sh/\(topic)/json?poll=1&since=10m")!)
        poll.timeoutInterval = 10

        while Date() < deadline {
            lock.lock()
            let active = isSearching
            lock.unlock()
            guard active else { throw CancellationError() }
            try Task.checkCancellation()

            if let (data, _) = try? await URLSession.shared.data(for: poll),
               let candidate = Self.peerCandidate(in: data, excludingRole: role, key: payloadKey) {
                return candidate
            }
            try await Task.sleep(nanoseconds: 1_000_000_000)
        }
        throw NSError(domain: "Signaling", code: 2,
                      userInfo: [NSLocalizedDescriptionKey: "Signaling timeout waiting for peer"])
    }

    public func stop() {
        lock.lock()
        isSearching = false
        lock.unlock()
    }
}

import Foundation
import Security

// Pairing identity, Keychain storage, and bootstrap PIN state.
//
// First contact: the client offers TLS-PSK identity "erd-b1.<salt>", whose
// key derives from the host's 8-digit bootstrap PIN. The host approves the
// device with an explicit prompt before any input or screen access is
// granted, and repeated PIN failures lock the bootstrap path globally.
// On approval the host generates a 256-bit pairing key and hands it to the
// client over the encrypted channel; both sides persist it in the Keychain.
// Later sessions use identity "erd-p1.<uuid>" with that key, which cannot
// be brute-forced offline the way the PIN can.
//
// Residual risk: an attacker who records the bootstrap handshake and cracks
// the PIN offline recovers that one session and the pairing key. Consent,
// lockout, and PIN expiry mitigate this; SPAKE2+ is the follow-up once a
// vetted Swift PAKE implementation is available.

/// A persisted trust relationship with one remote device.
public struct PairingRecord: Codable, Equatable, Identifiable, Sendable {
    public let id: String
    public var name: String
    public let key: Data
    public let addedAt: Date

    public init(id: String = UUID().uuidString, name: String, key: Data, addedAt: Date = Date()) {
        self.id = id
        self.name = name
        self.key = key
        self.addedAt = addedAt
    }

    public var pskIdentity: String { "erd-p1.\(id)" }
}

/// File-backed storage for pairing records.
///
/// Plaintext by design (user decision, 2026-09-01): the pairing key only
/// protects the network path — anyone with this user's disk access already
/// controls the machine, so the OS keychain adds friction (locked keychains
/// break headless/test sessions) without raising the real bar. File is 0600
/// under the user's Application Support directory.
public enum PairingStore {
    private static let fileLock = NSLock()

    private static var storeURL: URL {
        let dir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("EclipticRD", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir.appendingPathComponent("pairing-keys.json")
    }

    public static func loadAll() -> [PairingRecord] {
        fileLock.lock()
        defer { fileLock.unlock() }
        return loadAllUnlocked()
    }

    public static func load(id: String) -> PairingRecord? {
        loadAll().first { $0.id == id }
    }

    @discardableResult
    public static func save(_ record: PairingRecord) -> Bool {
        fileLock.lock()
        defer { fileLock.unlock() }
        // NSLock is not reentrant: call the unlocked variants, never the
        // public locked wrappers, while holding fileLock.
        var records = loadAllUnlocked().filter { $0.id != record.id }
        records.append(record)
        return writeUnlocked(records)
    }

    @discardableResult
    public static func delete(id: String) -> Bool {
        fileLock.lock()
        defer { fileLock.unlock() }
        var records = loadAllUnlocked()
        records.removeAll { $0.id == id }
        return writeUnlocked(records)
    }

    /// Caller must hold fileLock.
    private static func loadAllUnlocked() -> [PairingRecord] {
        guard let data = try? Data(contentsOf: storeURL),
              let records = try? JSONDecoder().decode([PairingRecord].self, from: data)
        else { return [] }
        return records
    }

    /// Caller must hold fileLock. Atomic 0600 write.
    private static func writeUnlocked(_ records: [PairingRecord]) -> Bool {
        guard let data = try? JSONEncoder().encode(records) else { return false }
        do {
            try data.write(to: storeURL, options: .atomic)
            try? FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: storeURL.path)
            return true
        } catch {
            ERDLog.error("[PairingStore] Failed to persist pairing: \(error)")
            return false
        }
    }
}

/// One TLS pre-shared key entry offered on a channel.
public struct ERDPSK: Equatable, Sendable {
    public let identity: String
    public let key: Data

    public init(identity: String, key: Data) {
        self.identity = identity
        self.key = key
    }
}

/// Host-side pairing authority: pending bootstrap PIN state, failure lockout,
/// and the set of PSKs the TCP listener should accept.
public final class PairingManager: @unchecked Sendable {
    public static let shared = PairingManager()

    private struct PendingPairing {
        let pin: String
        let expiresAt: Date
    }

    private let lock = NSLock()
    private var pending: PendingPairing?
    private var failureCount = 0
    private var failureWindowStart = Date.distantPast
    private var bootstrapLockedUntil = Date.distantPast

    // MARK: - Bootstrap PIN lifecycle (host)

    /// Start accepting bootstrap connections; returns the PIN to display.
    /// An explicit numeric PIN of the configured length (internet mode, where
    /// both sides type the same code) overrides the generated one.
    @discardableResult
    public func beginPairing(explicitPIN: String? = nil) -> String {
        var pin = ERDCrypto.randomPIN()
        if let explicitPIN, explicitPIN.count == ERDConstants.pinLength,
           explicitPIN.allSatisfy({ $0.isNumber }) {
            pin = explicitPIN
        }
        let pending = PendingPairing(pin: pin,
                                     expiresAt: Date().addingTimeInterval(ERDConstants.pairingPINExpiry))
        lock.lock()
        self.pending = pending
        failureCount = 0
        bootstrapLockedUntil = .distantPast
        lock.unlock()
        return pin
    }

    public func cancelPairing() {
        lock.lock()
        pending = nil
        lock.unlock()
    }

    public var isPairingActive: Bool {
        lock.withLock { pending != nil && pending!.expiresAt > Date() }
    }

    /// All PSKs the host listener should accept: every paired device plus the
    /// pending bootstrap entry while pairing is active and not locked out.
    public func hostPSKs() -> [ERDPSK] {
        lock.lock(); defer { lock.unlock() }
        var psks = PairingStore.loadAll().map { ERDPSK(identity: $0.pskIdentity, key: ERDCrypto.pairingPSK($0.key)) }
        if let pending, pending.expiresAt > Date(), Date() >= bootstrapLockedUntil {
            psks.append(ERDPSK(identity: Self.bootstrapIdentity,
                               key: ERDCrypto.bootstrapPSK(pin: pending.pin)))
        }
        return psks
    }

    /// Resolve one offered identity to its PSK (used by the TLS verify hook).
    public func resolvePSK(identity: String) -> ERDPSK? {
        hostPSKs().first { $0.identity == identity }
    }

    /// Record a failed bootstrap authentication. Returns true when bootstrap
    /// is now locked out.
    @discardableResult
    public func recordBootstrapFailure() -> Bool {
        lock.lock(); defer { lock.unlock() }
        let now = Date()
        if now.timeIntervalSince(failureWindowStart) > ERDConstants.pairingAttemptWindow {
            failureCount = 0
            failureWindowStart = now
        }
        failureCount += 1
        if failureCount >= ERDConstants.maxPairingAttempts {
            bootstrapLockedUntil = now.addingTimeInterval(ERDConstants.pairingLockout)
            pending = nil
            return true
        }
        return false
    }

    // MARK: - Grant / adopt (both sides)

    /// Host: mint + persist a pairing record for an approved bootstrap peer.
    public func grantPairing(hostname: String) -> PairingRecord {
        let record = PairingRecord(name: hostname, key: ERDCrypto.randomKey())
        PairingStore.save(record)
        return record
    }

    /// Client: persist a pairing record received from a host.
    public func adoptPairing(_ record: PairingRecord) {
        PairingStore.save(record)
    }

    public func pairedDevices() -> [PairingRecord] {
        PairingStore.loadAll().sorted { $0.addedAt > $1.addedAt }
    }

    public func revokePairing(id: String) {
        PairingStore.delete(id: id)
    }

    // MARK: - Client side

    public static let bootstrapIdentity = "erd-b1"

    /// The client connects either with a previously granted pairing key or,
    /// while pairing for the first time, with the bootstrap PSK for `pin`.
    public func clientPSK(pin: String) -> ERDPSK {
        ERDPSK(identity: Self.bootstrapIdentity, key: ERDCrypto.bootstrapPSK(pin: pin))
    }

    public func clientPSK(for record: PairingRecord) -> ERDPSK {
        ERDPSK(identity: record.pskIdentity, key: ERDCrypto.pairingPSK(record.key))
    }
}

private extension NSLock {
    func withLock<T>(_ body: () -> T) -> T {
        lock()
        defer { unlock() }
        return body()
    }
}

import Foundation

public class FrameSender {
    private let udpChannel: UDPChannel
    private var frameIdCounter: UInt32 = 0
    private let counterLock = NSLock()

    public init(udpChannel: UDPChannel) {
        self.udpChannel = udpChannel
    }

    public func sendFrame(data: Data, width: Int, height: Int, isKeyFrame: Bool) {
        counterLock.lock()
        frameIdCounter += 1
        let frameId = frameIdCounter
        counterLock.unlock()

        let maxPayload = ERDConstants.maxPayloadSize - FrameChunkPayload.headerSize
        let totalChunks = UInt16((data.count + maxPayload - 1) / maxPayload)

        guard totalChunks <= ERDConstants.maxChunksPerFrame else {
            ERDLog.error("[FrameSender] Frame too large: \(data.count) bytes, \(totalChunks) chunks")
            return
        }

        // 1. Send frame header via UDP
        let header = FrameHeaderPayload(
            frameId: frameId, width: UInt16(width), height: UInt16(height),
            isKeyFrame: isKeyFrame, totalChunks: totalChunks, totalSize: UInt32(data.count)
        )
        udpChannel.sendPacket(type: .frameHeader, payload: header.serialize())

        // 2. Send frame chunks via UDP
        var offset = 0
        var chunkIndex: UInt16 = 0
        while offset < data.count {
            let end = min(offset + maxPayload, data.count)
            let chunkData = data.subdata(in: offset..<end)
            let chunk = FrameChunkPayload(frameId: frameId, chunkIndex: chunkIndex, chunkData: chunkData)
            udpChannel.sendPacket(type: .frameChunk, payload: chunk.serialize())
            offset = end
            chunkIndex += 1
        }
    }

    public func sendCursorUpdate(x: Float, y: Float, cursorType: UInt8 = 0) {
        let cursor = CursorUpdate(x: x, y: y, cursorType: cursorType)
        udpChannel.sendPacket(type: .cursorUpdate, payload: cursor.serialize())
    }
}

import Foundation
import VideoToolbox
import CoreMedia

public enum VideoEncoderError: Error {
    case sessionCreationFailed
    case encodingFailed
}

public class VideoEncoder {
    private var session: VTCompressionSession?
    private let encoderQueue = DispatchQueue(label: "eclipticrd.encoder", qos: .userInteractive)
    private static let queueKey = DispatchSpecificKey<Bool>()
    private var frameCount: Int64 = 0
    private var retainedSelf: Unmanaged<VideoEncoder>?

    private let width: Int
    private let height: Int
    private let bitrate: Int
    private let fps: Int
    private var pendingForceKeyFrame = AtomicBool(false)

    public var onEncodedFrame: ((Data, Bool) -> Void)?

    public init(width: Int, height: Int, bitrate: Int = ERDConstants.defaultBitrate, fps: Int = ERDConstants.defaultFPS) {
        self.width = width; self.height = height; self.bitrate = bitrate; self.fps = fps
        encoderQueue.setSpecific(key: Self.queueKey, value: true)
    }

    deinit { stop() }

    public func start() throws {
        retainedSelf = Unmanaged.passRetained(self)

        let err = VTCompressionSessionCreate(
            allocator: kCFAllocatorDefault,
            width: Int32(width), height: Int32(height),
            codecType: kCMVideoCodecType_HEVC,
            encoderSpecification: nil, imageBufferAttributes: nil, compressedDataAllocator: nil,
            outputCallback: encoderCallback,
            refcon: retainedSelf!.toOpaque(),
            compressionSessionOut: &session
        )
        guard err == noErr, let session = session else {
            retainedSelf?.release()
            retainedSelf = nil
            throw VideoEncoderError.sessionCreationFailed
        }

        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_RealTime, value: kCFBooleanTrue)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AllowFrameReordering, value: kCFBooleanFalse)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: bitrate as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_MaxKeyFrameInterval, value: ERDConstants.keyFrameInterval as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: fps as CFTypeRef)
        VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ProfileLevel, value: kVTProfileLevel_HEVC_Main_AutoLevel)

        VTCompressionSessionPrepareToEncodeFrames(session)
        ERDLog.video("[Encoder] Started: H.265 \(width)x\(height) @\(bitrate/1_000_000)Mbps")
    }

    public func stop() {
        let work = {
            if let session = self.session {
                VTCompressionSessionInvalidate(session)
                self.session = nil
            }
            self.retainedSelf?.release()
            self.retainedSelf = nil
            self.frameCount = 0
            ERDLog.video("[Encoder] Stopped")
        }

        if DispatchQueue.getSpecific(key: Self.queueKey) == true {
            work()
        } else {
            encoderQueue.sync { work() }
        }
    }

    public func encode(_ sampleBuffer: CMSampleBuffer) {
        encoderQueue.async { [weak self] in
            guard let self = self else { return }
            guard let session = self.session else { return }
            guard let imageBuffer = CMSampleBufferGetImageBuffer(sampleBuffer) else {
                return
            }
            let pts = CMTime(value: self.frameCount, timescale: CMTimeScale(self.fps))
            self.frameCount += 1

            var frameProps: CFDictionary? = nil
            if self.pendingForceKeyFrame.value {
                self.pendingForceKeyFrame.value = false
                frameProps = [kVTEncodeFrameOptionKey_ForceKeyFrame: true] as CFDictionary
            }

            VTCompressionSessionEncodeFrame(session, imageBuffer: imageBuffer, presentationTimeStamp: pts,
                                            duration: .invalid, frameProperties: frameProps, sourceFrameRefcon: nil, infoFlagsOut: nil)
        }
    }

    public func forceKeyFrame() {
        pendingForceKeyFrame.value = true
    }

    public func updateBitrate(_ newBitrate: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_AverageBitRate, value: newBitrate as CFTypeRef)
        }
    }

    public func updateFPS(_ newFPS: Int) {
        encoderQueue.async { [weak self] in
            guard let self = self, let session = self.session else { return }
            VTSessionSetProperty(session, key: kVTCompressionPropertyKey_ExpectedFrameRate, value: newFPS as CFTypeRef)
        }
    }

    fileprivate func handleEncodedFrame(_ sampleBuffer: CMSampleBuffer) {
        guard let dataBuffer = CMSampleBufferGetDataBuffer(sampleBuffer) else { return }

        let isKeyFrame: Bool = {
            guard let attachments = CMSampleBufferGetSampleAttachmentsArray(sampleBuffer, createIfNecessary: false) as? [[CFString: Any]],
                  let first = attachments.first else { return true }
            return !(first[kCMSampleAttachmentKey_NotSync] as? Bool ?? false)
        }()

        var length = 0
        var dataPointer: UnsafeMutablePointer<Int8>?
        CMBlockBufferGetDataPointer(dataBuffer, atOffset: 0, lengthAtOffsetOut: nil, totalLengthOut: &length, dataPointerOut: &dataPointer)

        guard let pointer = dataPointer, length > 0 else { return }

        var frameData = Data()

        // For keyframes, prepend VPS/SPS/PPS from the format description
        // so the decoder can create its decoding session.
        if isKeyFrame, let formatDesc = CMSampleBufferGetFormatDescription(sampleBuffer) {
            var paramCount: Int = 0
            CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: 0,
                parameterSetPointerOut: nil, parameterSetSizeOut: nil, parameterSetCountOut: &paramCount, nalUnitHeaderLengthOut: nil)

            for i in 0..<paramCount {
                var paramPtr: UnsafePointer<UInt8>?
                var paramSize: Int = 0
                let status = CMVideoFormatDescriptionGetHEVCParameterSetAtIndex(formatDesc, parameterSetIndex: i,
                    parameterSetPointerOut: &paramPtr, parameterSetSizeOut: &paramSize, parameterSetCountOut: nil, nalUnitHeaderLengthOut: nil)
                if status == noErr, let ptr = paramPtr, paramSize > 0 {
                    // Write 4-byte AVCC length prefix + parameter set data
                    var len = UInt32(paramSize).bigEndian
                    frameData.append(Data(bytes: &len, count: 4))
                    frameData.append(Data(bytes: ptr, count: paramSize))
                }
            }
        }

        frameData.append(Data(bytes: pointer, count: length))
        onEncodedFrame?(frameData, isKeyFrame)
    }
}

private func encoderCallback(outputCallbackRefCon: UnsafeMutableRawPointer?,
                              sourceFrameRefCon: UnsafeMutableRawPointer?,
                              status: OSStatus,
                              infoFlags: VTEncodeInfoFlags,
                              sampleBuffer: CMSampleBuffer?) {
    guard status == noErr, let sampleBuffer = sampleBuffer, let refcon = outputCallbackRefCon else { return }
    let encoder = Unmanaged<VideoEncoder>.fromOpaque(refcon).takeUnretainedValue()
    encoder.handleEncodedFrame(sampleBuffer)
}

